// --------------------------------------------------
// 主逻辑
// --------------------------------------------------
// 五轴使能由 AxisEnableControl_PRG 根据 arReg_data[32] 统一控制。
// 这里不再每周期强制 TRUE，避免覆盖寄存器关闭使能命令。
arAi_data[9]:=bfiveDOF_state;
// 检测外部移动指令
trig_start(CLK := Move_5Axis_Sign=1);
IF trig_start.Q THEN

	log_msg := 'five-axis platform starts moving';
// 	logfb(write:=TRUE,sFileTestString:=log_msg);
	AppendLog(log_msg);

    // 使能所有轴（可放在这里一次性使能）
	bfiveDOF_state:=1;//开始运动
    AppendLog('status 0:6-axis start move' );
    step := 10;   // 开始安全顺序
END_IF

CASE step OF
    0: // 空闲
		bfiveDOF_state:=0;//开始运动
    // ---------- 阶段1：轴移动到目标 ----------
    10:
		FOR i := 1 TO AXIS_COUNT DO
			final_angle[i] := PlatformTargetAngle[i];
			final_vel[i]   := 360*6000/60;
			Axes[i].AxisDone := FALSE;  
			GVL.Axes[i].NeedMoveAxis := TRUE;
		END_FOR
        fbMove_2(AxisAngle := final_angle, AxisVel := final_vel, Execute := TRUE,Monitor:=TRUE);
        step := 20;

		log_msg := 'State 20: Start moving XYABC AXIS... ';
// 		logfb(write:=TRUE,sFileTestString:=log_msg);
		AppendLog(log_msg);;
    20:
        fbMove_2(AxisAngle := final_angle, AxisVel := final_vel, Execute := FALSE,Monitor:=TRUE);
        IF fbMove_2.allDone THEN
			log_msg := 'State 21: XYZABC AXIS movement completed';
// 			logfb(write:=TRUE,sFileTestString:=log_msg);
			AppendLog(log_msg);
        ELSIF fbMove_2.Error THEN
            bfiveDOF_state:=2;
        END_IF
		step := 0;



END_CASE

IF  first THEN              //如果没有文件，将创建文件
	fOpen.sFileName := sFileName;
    fOpen.eFileMode := FILE.MODE.MWRITEPLUS;//模式选择
    fOpen(xExecute := TRUE);
	IF  fOpen.xDone THEN
		 fOpen(xExecute := FALSE);
		  first:=FALSE;
	END_IF
END_IF


//执行写入操作
// IF  write THEN  //
// 	temp:=1;
//    write:=0;	
// END_IF

CASE temp OF
	0:
		IF write THEN
			temp:=1;
		END_IF

	1:fOpen.sFileName := sFileName;
      fOpen.eFileMode := FILE.MODE.MAPPD;//模式选择
      fOpen(xExecute := TRUE);
	  t0(IN:=1 , PT:=T#5MS);
	  IF t0.Q THEN
		 temp:=2; 
         t0(IN:=0);
	  END_IF

// 	 	IF fOpen.xDone THEN
//             fOpen(xExecute:=FALSE);
//             temp := 2;
//         END_IF
	2:  fWrite.hFile := fOpen.hFile;//文件句柄
		tempWriteStr := CONCAT(sFileTestString, '$R$N');

		fWrite.pBuffer := ADR(tempWriteStr);
		fWrite.szSize := LEN(tempWriteStr);	

        fWrite(xExecute := TRUE);//写入使能


// 		IF fWrite.xDone THEN
//             fWrite(xExecute:=FALSE);
//             temp := 3;
//         END_IF
		t0(IN:=1 , PT:=T#5MS);
	  IF t0.Q THEN
		 temp:=3; 
         t0(IN:=0); 
	  END_IF
	3:	fClose.hFile := fOpen.hFile;//文件句柄
        fClose(xExecute := TRUE);//使能关闭文件 
		t0(IN:=1 , PT:=T#5MS);
	  IF t0.Q THEN
		 temp:=4; 
         t0(IN:=0); 
	  END_IF
	4:	fWrite(xExecute := FALSE);//写入使能
	    fClose(xExecute :=FALSE);//使能关闭文件
		fOpen(xExecute := FALSE);//打开文件使能
		 t0(IN:=1 , PT:=T#5MS);
	  IF t0.Q THEN
		 temp:=0; 
         t0(IN:=0); 
	  END_IF
END_CASE


//读取操作
IF read THEN  //
	temp1:=1;
    read:=0;	
END_IF
CASE temp1 OF
	1:fOpen.sFileName := sFileName;
      fOpen.eFileMode := FILE.MODE.MREAD;//模式选择
      fOpen(xExecute := TRUE);
	  t1(IN:=1 , PT:=T#5MS);
	  IF t1.Q THEN
		 temp1:=2; 
         t1(IN:=0);
	  END_IF
	2:  fRead.hFile := fOpen.hFile;//文件句柄
        fRead.pBuffer := ADR(sBuffer);//放到缓存区
        fRead.szBuffer := SIZEOF(sBuffer);//长度  byte
        fRead(xExecute := TRUE);
		t1(IN:=1 , PT:=T#5MS);
	  IF t1.Q THEN
		 temp1:=3; 
         t1(IN:=0); 
	  END_IF
	3:	fClose.hFile := fOpen.hFile;//文件句柄
        fClose(xExecute := TRUE);//使能关闭文件 
		t1(IN:=1 , PT:=T#5MS);
	  IF t1.Q THEN
		 temp1:=4; 
         t1(IN:=0); 
	  END_IF
	4:	 fRead(xExecute := FALSE);//写入使能
	    fClose(xExecute :=FALSE);//使能关闭文件
		fOpen(xExecute := FALSE);//打开文件使能
		 t1(IN:=1 , PT:=T#5MS);
	  IF t1.Q THEN
		 temp1:=0; 
         t1(IN:=0); 
	  END_IF
END_CASE

// 申请锁（自旋）
WHILE g_QueueLock  DO ;  END_WHILE
g_QueueLock := TRUE;

nextHead := (g_QueueHead + 1) MOD 100;
IF nextHead = g_QueueTail THEN
    // 队列满：丢弃日志（可增加丢弃计数器）
    g_QueueLock := FALSE;
//     RETURN FALSE;
END_IF

pEntry := ADR(g_LogQueue[g_QueueHead]);
pEntry^.sMsg := sMsg;
pEntry^.timestamp := TIME_TO_UDINT( TIME() );//SysTimeGetMs();   // 获取时间戳
g_QueueHead := nextHead;
g_QueueCount := g_QueueCount + 1;

g_QueueLock := FALSE;
// RETURN TRUE;

// 从队列取出一条日志
WHILE g_QueueLock DO ; END_WHILE
g_QueueLock := TRUE;
IF g_QueueHead = g_QueueTail THEN
    g_QueueLock := FALSE;
    RETURN;
END_IF

entry := g_LogQueue[g_QueueTail];
nextTail := (g_QueueTail + 1) MOD 100;
g_QueueTail := nextTail;
g_QueueCount := g_QueueCount - 1;
g_QueueLock := FALSE;

// --- 以下将 entry 写入环形缓冲区 g_LogBuffer（单线程，无需锁）---
// 注意：这里直接操作 g_LogBuffer，与 Modbus 映射代码共享
// 但 Modbus 映射代码只读，不会写，所以安全
// 但需要确保 Modbus 映射读取时不会读到一半更新的条目（可以通过双缓冲或版本号避免，但通常可以接受）

newWriteIdx := (g_LogBuffer.writeIdx + 1) MOD g_LogBuffer.maxSize;
IF newWriteIdx = g_LogBuffer.readIdx THEN
    // 缓冲区满，覆盖最旧
    g_LogBuffer.readIdx := (g_LogBuffer.readIdx + 1) MOD g_LogBuffer.maxSize;
    // count 不变
ELSE
    g_LogBuffer.count := g_LogBuffer.count + 1;
END_IF

pBufEntry := ADR(g_LogBuffer.entries[g_LogBuffer.writeIdx]);
pBufEntry^.sMessage := entry.sMsg;
pBufEntry^.length := LEN(entry.sMsg);
pBufEntry^.timestamp := entry.timestamp;
g_LogBuffer.writeIdx := newWriteIdx;






// ================================
// 5轴点动控制
// ================================


fbJogY(
    Axis := AXIS_Y,
    xServoOn := xServoEnable,
    xReset := FALSE,
    xJogFwd := xJogFwd[2],
    xJogRev := xJogRev[2],
    xLimitFwd := FALSE,
    xLimitRev := FALSE,
    lrJogVel := 100.0,
    lrAcc := 100.0,
    lrDec := 200.0,
    lrJerk := 0.0
);


// 伺服上使能
 fbPower(
     Axis :=Axis,
     Enable := xServoOn,
     bRegulatorOn := TRUE,
     bDriveStart := TRUE
 );


 // 故障复位，上升沿触发
 rtReset(CLK := xReset);

 fbReset(
     Axis :=Axis,
     Execute := rtReset.Q
 );

 // 防止正反同时点动
 xConflict := xJogFwd AND xJogRev;

 // 点动允许条件
 xCmdFwd := xJogFwd
            AND  fbPower.Status
           AND NOT xJogRev
            AND NOT xLimitFwd
           AND NOT xConflict;

 xCmdRev := fbPower.Status
            AND xJogRev
            AND NOT xJogFwd
            AND NOT xLimitRev
            AND NOT xConflict;

 // 点动控制：按住走，松开按减速度停止
 fbJog(
     Axis := Axis,
     JogForward := xCmdFwd,
     JogBackward := xCmdRev,
     Velocity := lrJogVel,
     Acceleration := lrAcc,
     Deceleration := lrDec,
     Jerk := lrJerk
 );

 // 状态输出
 xReady := fbPower.Status;
 xMoving := fbJog.Busy;

 xFault := fbPower.Error OR fbReset.Error OR fbJog.Error OR xConflict;

 IF fbPower.Error THEN
     iFaultSrc := 1;
 ELSIF fbReset.Error THEN
     iFaultSrc := 2;
 ELSIF fbJog.Error THEN
     iFaultSrc := 3;
 ELSIF xConflict THEN
     iFaultSrc := 10;
 ELSE
     iFaultSrc := 0;
 END_IF;

 xJogFwdCmd := xCmdFwd;
 xJogRevCmd := xCmdRev;
 xJogError := fbJog.Error;
 eJogErrorID := fbJog.ErrorID;
 xJogAborted := fbJog.CommandAborted;

xJogMode[1] := (arReg_data[19] AND WORD#16#0001) <> WORD#0; // X
// ================================ // 5轴点动控制 // ================================
fbJogX( Axis := AXIS_X, xServoOn := xServoEnable, xReset := FALSE, xJogFwd := xJogFwd[1], xJogRev := xJogRev[1], xLimitFwd := FALSE, xLimitRev := FALSE, lrJogVel := 100.0, lrAcc := 100.0, lrDec := 200.0, lrJerk := 0.0 );






